def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay settings on defaults (mode=fast, level=3) and return resulting values."""
    pre keys.len() == values.len()
    ex settings(keys=[], values=[]) == ["fast", "3"]
    ex settings(keys=["mode"], values=["slow"]) == ["slow", "3"]
    ex settings(keys=["opt"], values=["yes"]) == ["fast", "3", "yes"]
    mode = "fast"
    level = "3"
    extras: dict[str, str] = {}
    extra_order: list[str] = []
    for i in range(keys.len()):
        k = keys[i]
        v = values[i]
        if k == "mode":
            mode = v.copy()
        elif k == "level":
            level = v.copy()
        else:
            if k not in extras:
                extra_order.append(k.copy())
            extras[k] = v.copy()
    res = [mode, level]
    for k in extra_order:
        res.append(extras.get(k) else "")
    return res

